class BankAccount {boolean opened=false;int balance=0;void open()throws BankAccountActionInvalidException{if(opened)throw new BankAccountActionInvalidException();opened=true;balance=0;}void check()throws BankAccountActionInvalidException{if(!opened)throw new BankAccountActionInvalidException();}void close()throws BankAccountActionInvalidException{check();opened=false;}int getBalance()throws BankAccountActionInvalidException{check();return balance;}void deposit(int n)throws BankAccountActionInvalidException{check();if(n<0)throw new BankAccountActionInvalidException();balance+=n;}void withdraw(int n)throws BankAccountActionInvalidException{check();if(n<0||n>balance)throw new BankAccountActionInvalidException();balance-=n;}}